const ctx = $('Input').first().json;
const m = String(ctx.google_drive_folder ?? '').match(/[-\w]{25,}/);
return [{ json: { ...ctx, drive_folder_id: m ? m[0] : '' } }];

const files = ($json.files ?? []).slice(0, 2);
if (!files.length) { return [{ json: { no_stubs: true } }]; }
return files.map(f => ({ json: f }));

const ctx = $('Input').first().json;
const items = $input.all();
const docs = [];
for (const it of items) {
  const b64 = it.binary?.data?.data;
  if (b64) docs.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } });
}
if (!docs.length) { return [{ json: { ...ctx, payroll: { employees: [], notes: ['No pay stubs found in Drive folder'] } } }]; }
const payload = {
  model: 'claude-opus-4-8', max_tokens: 8000,
  system: "You are extracting payroll data from uploaded pay stub documents for a CPA's tax projection. Extract per employee: gross pay YTD, federal withholding YTD, state withholding YTD, pay period, and pay frequency if visible. Extract only what is explicitly on the stubs; use null for anything not found. Output only the JSON schema.",
  messages: [{ role: 'user', content: [...docs, { type: 'text', text: 'Extract the payroll data from these pay stubs for client ' + ctx.client_name + '.' }] }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["employees", "notes"], "properties": {"employees": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["name", "gross_ytd", "federal_withholding_ytd", "state_withholding_ytd", "period_end"], "properties": {"name": {"type": ["string", "null"]}, "gross_ytd": {"type": ["number", "null"]}, "federal_withholding_ytd": {"type": ["number", "null"]}, "state_withholding_ytd": {"type": ["number", "null"]}, "period_end": {"type": ["string", "null"]}}}}, "notes": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { payload } }];

const ctx = $('Input').first().json;
if ($json.payroll) { return [{ json: $json }]; }
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
return [{ json: { ...ctx, payroll: out } }];
